if (pm.response.code === 200) {
  pm.test("Returns metadata for all 7 config files", function () {
    const j = pm.response.json();
    pm.expect(j.files).to.have.lengthOf(7);
    const names = j.files.map(f => f.file);
    ["pii-rules.json","secret-patterns.json","injection-phrases.json","file-signatures.json","token-limits.json","scoring-weights.json","decision-thresholds.json"].forEach(n => {
      pm.expect(names).to.include(n);
    });
    j.files.forEach(f => {
      pm.expect(f.file).to.be.a('string');
      pm.expect(f.ruleCount).to.be.a('number');
    });
  });
}

pm.test("ruleCount matches the real config file contents", function () {
  const j = pm.response.json();
  const byFile = Object.fromEntries(j.files.map(f => [f.file, f]));
  pm.expect(byFile["pii-rules.json"].ruleCount).to.eql(13);
  pm.expect(byFile["pii-rules.json"].version).to.eql(5);
  pm.expect(byFile["secret-patterns.json"].ruleCount).to.eql(7);
  pm.expect(byFile["injection-phrases.json"].ruleCount).to.eql(10);
  pm.expect(byFile["file-signatures.json"].ruleCount).to.eql(6);
  pm.expect(byFile["token-limits.json"].ruleCount).to.eql(2);
  pm.expect(byFile["scoring-weights.json"].ruleCount).to.eql(4);
  pm.expect(byFile["decision-thresholds.json"].ruleCount).to.eql(2);
});

