pm.test("prompt-injection-detector fires both rules, verdict BLOCK, both payload fields null", function () {
  const j = pm.response.json();
  const inj = j.results.find(r => r.stage === "prompt-injection-detector");
  const types = inj.matches.map(m => m.type).sort();
  pm.expect(types).to.eql(["BLOCKLIST_PHRASE","INSTRUCTION_OVERRIDE"]);
  pm.expect(j.decision.verdict).to.eql("BLOCK");
  pm.expect(j.decision.totalScore).to.eql(200);
  pm.expect(j.finalPayload).to.eql(null);
  pm.expect(j.decision.safePayload).to.eql(null);
});

pm.test("secret-detector attributes the match to SECRET_AWS_ACCESS_KEY", function () {
  const secret = pm.response.json().results.find(r => r.stage === "secret-detector");
  pm.expect(secret.matches[0].ruleId).to.eql("SECRET_AWS_ACCESS_KEY");
  pm.expect(secret.matches[0].type).to.eql("AWS_ACCESS_KEY");
  pm.expect(secret.matches[0].severity).to.eql("critical");
});

pm.test("shortCircuited at token-size-validator with the exact rule and meta", function () {
  const j = pm.response.json();
  pm.expect(j.shortCircuited).to.eql(true);
  pm.expect(j.shortCircuitStage).to.eql("token-size-validator");
  const tok = j.results.find(r => r.stage === "token-size-validator");
  pm.expect(tok.matches[0].ruleId).to.eql("TOKEN_LIMIT_EXCEEDED");
  pm.expect(tok.meta.maxTokens).to.eql(4096);
  pm.expect(tok.meta.targetModel).to.eql("default");
});

pm.test("token-size-validator meta reflects the gpt-family 8192 limit", function () {
  const tok = pm.response.json().results.find(r => r.stage === "token-size-validator");
  pm.expect(tok.meta.targetModel).to.eql("gpt-family");
  pm.expect(tok.meta.maxTokens).to.eql(8192);
});

pm.test("file-validator has zero matches and the pipeline did not short-circuit", function () {
  const j = pm.response.json();
  const fv = j.results.find(r => r.stage === "file-validator");
  pm.expect(fv.matches).to.eql([]);
  pm.expect(j.shortCircuited).to.eql(false);
});

pm.test("file-validator hard-fails with EXTENSION_SIGNATURE_MISMATCH, detectedType PNG", function () {
  const j = pm.response.json();
  pm.expect(j.shortCircuited).to.eql(true);
  pm.expect(j.shortCircuitStage).to.eql("file-validator");
  const fv = j.results.find(r => r.stage === "file-validator");
  pm.expect(fv.matches[0].ruleId).to.eql("EXTENSION_SIGNATURE_MISMATCH");
  pm.expect(fv.meta.detectedType).to.eql("PNG");
});
